CREATE TABLE IF NOT EXISTS ai_providers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, driver VARCHAR(80) NOT NULL, base_url VARCHAR(500) NULL, default_model VARCHAR(150) NOT NULL, api_key_encrypted TEXT NULL, options JSON NULL, enabled TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS ai_knowledge_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, source_type VARCHAR(50) NOT NULL, source_url VARCHAR(500) NULL, locale VARCHAR(20) NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS ai_knowledge_chunks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, document_id BIGINT UNSIGNED NOT NULL, content MEDIUMTEXT NOT NULL, embedding JSON NULL, token_count INT UNSIGNED NOT NULL DEFAULT 0, sort_order INT NOT NULL DEFAULT 0, INDEX(document_id));
CREATE TABLE IF NOT EXISTS ai_conversations (id CHAR(36) PRIMARY KEY, locale VARCHAR(20) NOT NULL, visitor_name VARCHAR(150) NULL, visitor_email VARCHAR(190) NULL, channel ENUM('ai','human') NOT NULL DEFAULT 'ai', status ENUM('open','queued','assigned','closed') NOT NULL DEFAULT 'open', assigned_user_id BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX(status));
CREATE TABLE IF NOT EXISTS ai_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, conversation_id CHAR(36) NOT NULL, role ENUM('visitor','assistant','agent','system') NOT NULL, content TEXT NOT NULL, provider_slug VARCHAR(80) NULL, created_at DATETIME NOT NULL, INDEX(conversation_id));
CREATE TABLE IF NOT EXISTS ai_escalation_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, trigger_type ENUM('phrase','no_answer','provider_unavailable','manual') NOT NULL, trigger_value VARCHAR(500) NULL, active TINYINT(1) NOT NULL DEFAULT 1, priority INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
